#!/usr/bin/env python3
"""Verify and independently replay only the manifest-selected delivery files."""
import argparse,hashlib,json,os,pathlib,subprocess,sys
sha=lambda b:hashlib.sha256(b).hexdigest()
def require(ok,message):
 if not ok:raise ValueError(message)
p=argparse.ArgumentParser();p.add_argument('--repo',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);p.add_argument('--result',type=pathlib.Path,required=True);a=p.parse_args();here=pathlib.Path(__file__).resolve().parent
require(not a.output.exists(),'isolated output must be fresh');a.output.mkdir(parents=True);selected=a.output/'selection';selected.mkdir();raw=(here/'DELIVERY-FILES.json').read_bytes();manifest=json.loads(raw);expected={row['path']:row for row in manifest['files']};require(len(expected)==manifest['file_count'],'duplicate manifest path')
