 q=pathlib.PurePosixPath(name);require(not q.is_absolute() and '..' not in q.parts and '\\' not in name,'unsafe selection path');data=(here/name).read_bytes();require(len(data)==row['bytes'] and sha(data)==row['sha256'],'frozen source file differs '+name);dest=selected/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(data)
