proc=subprocess.run([sys.executable,str(selected/'replay_evidence.py'),'--repo',str(a.repo.resolve()),'--output',str((a.output/'replayed').resolve())],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,env=os.environ|{'PYTHONDONTWRITEBYTECODE':'1'});(a.output/'replay.log').write_bytes(proc.stdout);require(proc.returncode==0,'isolated replay failed; see replay.log');result_path=a.output/'replayed/results/result.json';result=json.loads(result_path.read_bytes());require(result['installed_gate_status']=='PASS' and result['platform_locale_discovery_status']=='PASS_BOUND_INSTALLED_PLATFORM_LOCALE_DISCOVERY','isolated installed/platform gates did not pass')
report={'status':'PASS_FRESH_MANIFEST_SELECTED_ISOLATED_REPLAY','head':manifest['head'],'tree':manifest['tree'],'merge':manifest['merge'],'run_id':manifest['run_id'],'input_selection_manifest_sha256':sha(raw),'selected_input_files':len(expected),'selected_input_bytes':sum(x['bytes'] for x in expected.values()),'exit_code':proc.returncode,'replay_result_sha256':sha(result_path.read_bytes()),'replay_log_sha256':sha(proc.stdout),'limit':'Uses only the copied bounded selection and separately supplied exact checkout. No CI downloads or Android execution. New documentation/verification receipts may subsequently be added to the final selection.'};a.result.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
